INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, body_html, regions_json, published, is_custom)
     VALUES ('00000000-0000-4000-8000-0000b537f6f5', 'budget-committee', 'Budget Committee', 'NRCGA Programs', 'The Budget Committee oversees NRCGA''s financial planning, budget development, and fiscal responsibility to ensure the organization''s long-term sustainability.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"The Budget Committee plays a critical role in NRCGA''s financial management and strategic planning. This committee is responsible for developing annual budgets, monitoring financial performance, and ensuring the organization''s resources are allocated effectively to support our mission and programs.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Key Responsibilities","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"• ✓ Develop and review annual operating budgets\n• ✓ Monitor financial performance and expenditures\n• ✓ Provide financial oversight and recommendations to the Board\n• ✓ Ensure fiscal responsibility and transparency","style":{"align":"left","textSize":"md","textColor":"default"}}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Get Involved","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Click here to view your committee enrollment.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Committee Enrollment","url":"committee-enrollment.html","style":{"align":"left"}},{"type":"text","body":"Interested in participating in this committee?","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Contact Us","url":"contact.html","style":{"align":"left"}}]}]', '<!-- Main Content -->
    <section class="content-section">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem;">
                    The Budget Committee plays a critical role in NRCGA''s financial management and strategic planning. This committee is responsible for developing annual budgets, monitoring financial performance, and ensuring the organization''s resources are allocated effectively to support our mission and programs.
                </p>

                <div style="background: var(--bg-light); padding: 2rem; border-radius: 12px; margin: 2rem 0;">
                    <h3 style="margin-bottom: 1.5rem; color: var(--primary);">Key Responsibilities</h3>
                    <ul style="list-style: none; padding: 0; display: flex; flex-direction: column; gap: 1rem;">
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Develop and review annual operating budgets</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Monitor financial performance and expenditures</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Provide financial oversight and recommendations to the Board</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Ensure fiscal responsibility and transparency</span>
                        </li>
                    </ul>
                </div>

            </div>
        </div>
    </section>

    <!-- Get Involved CTA -->
    <section class="content-section bg-light">
        <div class="container">
            <div class="cta-content" style="text-align: center;">
                <h2>Get Involved</h2>
                <p>Click here to view your committee enrollment.</p>
                <div style="display: flex; justify-content: center; gap: 1.5rem; margin-top: 3rem; flex-wrap: wrap;">
                    <a href="committee-enrollment.html" class="btn btn-primary">Committee Enrollment</a>
                </div>
                <br>
                <p>Interested in participating in this committee?</p>
                <div style="display: flex; justify-content: center; gap: 1.5rem; margin-top: 3rem; flex-wrap: wrap;">
                    <a href="contact.html" class="btn btn-primary">Contact Us</a>
                </div>
            </div>
        </div>
    </section>', NULL, 1, 0);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, body_html, regions_json, published, is_custom)
     VALUES ('00000000-0000-4000-8000-0000e8c2e4a7', '811-day', '811 Day (August 11)', 'NRCGA Programs', 'Public awareness outreach to spread "Call 811 Before You Dig" across Nevada communities.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/811 day/811Day2024b.jpg","alt":"","caption":"","width":"full","align":"center"}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Join us at the Ball park!","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"image","url":"assets/images/programs/811 day/811day26flyer.png","alt":"A day at the ball park!","caption":"","width":"full","align":"left"},{"type":"cta_button","label":"Get Your Tickets!","url":"zero-at-fault-damages.html","style":{"align":"left"}},{"type":"text","body":"Every year on August 11 (8/11), NRCGA joins the national effort to raise awareness about the importance of calling 811 before digging. This annual event brings together stakeholders from across Nevada''s damage prevention community to spread the message of safe digging practices.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"This year the NRCGA is celebrating 811 Day with a night at the ballpark. Join us at the Aviators Stadium for good company, great baseball, and a shared commitment to safe digging. Tickets are just $8.11, fitting for the occasion!","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Why 811 Day Matters","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"• ✓ Raises public awareness about the importance of calling 811 before any digging project\n• ✓ Prevents utility damages that can cause injuries, service disruptions, and costly repairs\n• ✓ Builds a culture of safety across Nevada communities\n• ✓ Brings together stakeholders to celebrate damage prevention achievements","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":2,"text":"How We Celebrate","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"NRCGA organizes various activities and events throughout Nevada to mark 811 Day, including:","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":2,"gap":"md","items":[{"icon":"✓","title":"Community Events","body":"Public outreach events at community centers, parks, and public spaces"},{"icon":"✓","title":"Educational Workshops","body":"Training sessions for homeowners, contractors, and excavators"},{"icon":"✓","title":"Media Campaigns","body":"Social media and traditional media outreach to reach wider audiences"},{"icon":"✓","title":"Partnership Activities","body":"Collaborations with utilities, contractors, and community organizations"}]}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/811 day/LVBallpark811Day2024.jpg","alt":"","caption":"","width":"full","align":"center"}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"image","url":"assets/images/programs/811 day/1722879392324-e1723053578491.jpg","alt":"811 Day Event 2024","caption":"","width":"lg","align":"left"}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Get Involved","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Click here to view your committee enrollment.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Committee Enrollment","url":"committee-enrollment.html","style":{"align":"left"}},{"type":"text","body":"Interested in participating in this program?","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Contact Us","url":"contact.html","style":{"align":"left"}}]}]', '<!-- Hero Image Background -->
    <section style="position: relative; height: 60vh; min-height: 400px; background-image: url(''assets/images/programs/811 day/811Day2024b.jpg''); background-size: cover; background-position: center; background-attachment: fixed; background-repeat: no-repeat;">
        <div style="position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0, 0, 0, 0.4);"></div>
    </section>

    <!-- Main Content -->
    <section class="content-section">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                
                <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <h2>Join us at the Ball park!</h2>

                <div style="margin-top: 2rem;">
                    <div style="text-align: center; margin-top: 1.5rem;">
                        <img src="assets/images/programs/811 day/811day26flyer.png" alt="A day at the ball park!" style="max-width: 1200px; width: 100%; height: auto;" onerror="this.style.display=''none''">
                        <a href="zero-at-fault-damages.html" class="btn btn-primary">Get Your Tickets!</a>
                    </div>
                </div>
                    
                <div style="margin-top: 2rem;">
                
                    <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem; margin-top: 2rem;">
                    Every year on August 11 (8/11), NRCGA joins the national effort to raise awareness about the importance of calling 811 before digging. This annual event brings together stakeholders from across Nevada''s damage prevention community to spread the message of safe digging practices.
                </p>
                    
                    <p style="margin-bottom: 1.5rem;">This year the NRCGA is celebrating 811 Day with a night at the ballpark. Join us at the Aviators Stadium for good company, great baseball, and a shared commitment to safe digging. Tickets are just $8.11, fitting for the occasion!</p>
                </div>
            </div>
        </div>

                <div style="background: var(--bg-light); padding: 2rem; border-radius: 12px; margin: 2rem 0;">
                    <h3 style="margin-bottom: 1.5rem; color: var(--primary);">Why 811 Day Matters</h3>
                    <ul style="list-style: none; padding: 0; display: flex; flex-direction: column; gap: 1rem;">
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Raises public awareness about the importance of calling 811 before any digging project</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Prevents utility damages that can cause injuries, service disruptions, and costly repairs</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Builds a culture of safety across Nevada communities</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Brings together stakeholders to celebrate damage prevention achievements</span>
                        </li>
                    </ul>
                </div>

                <h2 style="margin-top: 3rem; margin-bottom: 1.5rem;">How We Celebrate</h2>
                <p style="margin-bottom: 2rem; color: var(--text-light);">
                    NRCGA organizes various activities and events throughout Nevada to mark 811 Day, including:
                </p>

                <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 1.5rem; margin-top: 2rem;">
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Community Events</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Public outreach events at community centers, parks, and public spaces</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Educational Workshops</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Training sessions for homeowners, contractors, and excavators</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Media Campaigns</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Social media and traditional media outreach to reach wider audiences</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Partnership Activities</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Collaborations with utilities, contractors, and community organizations</p>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <!-- Photo Gallery Background -->
    <section style="position: relative; height: 50vh; min-height: 350px; background-image: url(''assets/images/programs/811 day/LVBallpark811Day2024.jpg''); background-size: cover; background-position: center; background-attachment: fixed; background-repeat: no-repeat;">
        <div style="position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0, 0, 0, 0.3);"></div>
    </section>

    <!-- Additional Photo -->
    <section class="content-section bg-light">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <div style="text-align: center;">
                    <img src="assets/images/programs/811 day/1722879392324-e1723053578491.jpg" alt="811 Day Event 2024" style="width: 100%; max-width: 800px; border-radius: 12px; box-shadow: var(--shadow-md);" onerror="this.style.display=''none''">
                </div>
            </div>
        </div>
    </section>

    <!-- Get Involved CTA -->
    <section class="content-section bg-light">
        <div class="container">
            <div class="cta-content" style="text-align: center;">
                <h2>Get Involved</h2>
                <p>Click here to view your committee enrollment.</p>
                <div style="display: flex; justify-content: center; gap: 1.5rem; margin-top: 3rem; flex-wrap: wrap;">
                    <a href="committee-enrollment.html" class="btn btn-primary">Committee Enrollment</a>
                </div>
                <br>
                <p>Interested in participating in this program?</p>
                <div style="display: flex; justify-content: center; gap: 1.5rem; margin-top: 3rem; flex-wrap: wrap;">
                    <a href="contact.html" class="btn btn-primary">Contact Us</a>
                </div>
            </div>
        </div>
    </section>', NULL, 1, 0);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, body_html, regions_json, published, is_custom)
     VALUES ('00000000-0000-4000-8000-00002d73d4e9', 'craig-rogers-award', 'Craig Rogers Award', 'NRCGA Programs', 'Honoring Excellence in Damage Prevention in memory of our dear friend & colleague', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"grid","columns":3,"gap":"md","items":[{"icon":"✓","title":"","body":"\"I just want to do what is right.\""}]}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Why This Award Exists","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"The Craig Rogers Award celebrates leaders who:","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":4,"gap":"md","items":[{"icon":"🛡️","title":"","body":"Demonstrate exceptional dedication"},{"icon":"🔨","title":"","body":"Deliver tangible improvements"},{"icon":"📖","title":"","body":"Share knowledge generously"},{"icon":"🤝","title":"","body":"Uphold integrity and character"}]},{"type":"text","body":"This recognition is not only about past achievements—it sets the standard for the future of damage prevention in Nevada.","style":{"align":"left","textSize":"md","textColor":"default"}}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Hall of Heroes","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"heading","level":3,"text":"Kristen Garcia","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Winner of the 2026!.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"image","url":"assets/images/programs/craig rogers/kristenwon.jpg","alt":"The Rogers Cup","caption":"","width":"full","align":"left"},{"type":"heading","level":3,"text":"The First of Many","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Kristen Garcia has made history as the first-ever recipient of the Craig Rogers Award. This honor recognizes an individual whose dedication to damage prevention and the 811 community reflects the very values Craig Rogers stood for. Kristen, we are so proud to celebrate you.","style":{"align":"left","textSize":"md","textColor":"default"}}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Who Was Craig Rogers?","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"image","url":"assets/images/programs/craig rogers/CraigInField.png","alt":"Craig Rogers in the field","caption":"","width":"full","align":"left"},{"type":"text","body":"Video courtesy of USA North 811. https://www.youtube.com/@usanorth811","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Craig Rogers exemplified the best of Nevada''s damage prevention community—integrity, mentorship, and a relentless focus on doing the right thing. He built bridges across stakeholders and raised the bar for safety culture. This award honors professionals who continue that legacy and inspire others to follow.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"\"When we get there, we are going to look at the entire piece. What are you doing as an excavator? What are you doing as a utility operator? And trying to figure out how we can make things better.\"","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"— Craig Rogers","style":{"align":"left","textSize":"md","textColor":"default"}}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Nominate a Champion","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Know someone who exemplifies Craig Rogers'' legacy? Nominate them for the Craig Rogers Award.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Nominee name *","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Your name","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Email *","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Organization","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Nomination statement","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Submit nomination","style":{"align":"left","textSize":"md","textColor":"default"}}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Get Involved","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Click here to view your committee enrollment.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Committee Enrollment","url":"committee-enrollment.html","style":{"align":"left"}},{"type":"text","body":"Interested in participating in this committee?","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Contact Us","url":"contact.html","style":{"align":"left"}}]}]', '<!-- Quote Section with Photo -->
    <section class="content-section">
        <div class="container">
            <div style="max-width: 900px; margin: 0 auto;">
                <div style="display: grid; grid-template-columns: 1fr 2fr; gap: 2rem; align-items: center; margin-bottom: 2rem;">
                    <div style="text-align: center;">
                        <img src="assets/images/programs/craig rogers/craig1.jpg" alt="Craig Rogers" style="width: 100%; max-width: 300px; border-radius: 12px; box-shadow: var(--shadow-md);" onerror="this.style.display=''none''">
                    </div>
                    <div style="padding: 2rem; background: var(--bg-light); border-radius: 12px; border-left: 4px solid var(--primary);">
                        <p style="font-size: 1.5rem; font-style: italic; color: var(--text-primary); margin-bottom: 1rem;">
                            "I just want to do what is right."
                        </p>
                        <p style="color: var(--text-light);">— Craig Rogers</p>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <!-- Why This Award Exists -->
    <section class="content-section bg-light">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <h2>Why This Award Exists</h2>
                <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem;">
                    The Craig Rogers Award celebrates leaders who:
                </p>
                <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1.5rem; margin-top: 2rem;">
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; text-align: center;">
                        <div style="font-size: 2rem; margin-bottom: 0.5rem;">🛡️</div>
                        <p style="font-weight: 600; margin-bottom: 0.5rem;">Demonstrate exceptional dedication</p>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">to preventing utility damages</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; text-align: center;">
                        <div style="font-size: 2rem; margin-bottom: 0.5rem;">🔨</div>
                        <p style="font-weight: 600; margin-bottom: 0.5rem;">Deliver tangible improvements</p>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">in safety and performance</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; text-align: center;">
                        <div style="font-size: 2rem; margin-bottom: 0.5rem;">📖</div>
                        <p style="font-weight: 600; margin-bottom: 0.5rem;">Share knowledge generously</p>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">raising the skills of peers</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; text-align: center;">
                        <div style="font-size: 2rem; margin-bottom: 0.5rem;">🤝</div>
                        <p style="font-weight: 600; margin-bottom: 0.5rem;">Uphold integrity and character</p>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">in every decision</p>
                    </div>
                </div>
                <p style="margin-top: 2rem; font-style: italic; color: var(--text-light);">
                    <strong>This recognition is not only about past achievements—it sets the standard for the future of damage prevention in Nevada.</strong>
                </p>
            </div>
        </div>
    </section>

<!-- Several sections commented out to minimize site fluff -->
    <!-- 
     Guidelines & Eligibility 
    <section class="content-section">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <h2>Guidelines & Eligibility</h2>
                
                <div style="margin-top: 2rem;">
                    <h3 style="margin-bottom: 1rem; color: var(--primary);">Who can be nominated</h3>
                    <p style="margin-bottom: 1.5rem;">Any Nevada-based professional active in damage prevention (excavators, operators, locators, engineers, public officials, etc.).</p>
                </div>

                <div style="margin-top: 2rem;">
                    <h3 style="margin-bottom: 1rem; color: var(--primary);">Nominee Experience</h3>
                    <p style="margin-bottom: 1.5rem;">Minimum 3 years in Nevada damage prevention or closely related roles.</p>
                </div>

                <div style="margin-top: 2rem;">
                    <h3 style="margin-bottom: 1rem; color: var(--primary);">What to include</h3>
                    <p style="margin-bottom: 1.5rem;">Specific examples of contributions, measurable outcomes, and a brief statement on mentorship and character.</p>
                </div>
            </div>
        </div>
    </section>

