:[{"type":"heading","level":2,"text":"Get Involved","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Click here to view your committee enrollment.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Committee Enrollment","url":"committee-enrollment.html","style":{"align":"left"}},{"type":"text","body":"Interested in participating in this committee?","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Contact Us","url":"contact.html","style":{"align":"left"}}]}]', '<!-- Hero Image Background -->
    <section style="position: relative; height: 50vh; min-height: 350px; background-image: url(''assets/images/programs/education/OutsideTraining.jpg''); background-size: cover; background-position: center; background-attachment: fixed; background-repeat: no-repeat;">
