     VALUES ('00000000-0000-4000-8000-0000b7569434', 'golf-tournament', 'Golf Tournament Fundraiser', 'NRCGA Programs', 'Proceeds support outreach, education, and damage prevention programs statewide.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/golf/NRCGAGolf.jpg","alt":"","caption":"","width":"full","align":"center"}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"The NRCGA Golf Tournament is an annual fundraising event that brings together members of Nevada''s damage prevention community for a day of golf, networking, and fun. Proceeds from the tournament directly support NRCGA''s outreach, education, and damage prevention programs across the state.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"How Your Support Helps","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"• ✓ Funds safety training programs for excavators and locators\n• ✓ Supports community outreach and public awareness campaigns\n• ✓ Enables recognition programs like the Silver Shovel Awards\n• ✓ Helps organize events like 811 Day and the Utility Locate Rodeo","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":2,"text":"Tournament Details","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"The NRCGA Golf Tournament typically includes:","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":2,"gap":"md","items":[{"icon":"✓","title":"18-Hole Tournament","body":"Scramble format with prizes for top teams"},{"icon":"✓","title":"Networking Opportunities","body":"Connect with industry professionals and stakeholders"},{"icon":"✓","title":"Sponsorship Packages","body":"Multiple sponsorship levels available for businesses"},{"icon":"✓","title":"Awards & Recognition","body":"Prizes, raffles, and recognition for participants"}]}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Get Involved","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Click here to view your committee enrollment.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Committee Enrollment","url":"committee-enrollment.html","style":{"align":"left"}},{"type":"text","body":"Interested in participating in or sponsoring the golf tournament?","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Contact Us","url":"contact.html","style":{"align":"left"}}]}]', '<!-- Hero Image Background -->
    <section style="position: relative; height: 60vh; min-height: 400px; background-image: url(''assets/images/programs/golf/NRCGAGolf.jpg''); background-size: cover; background-position: center; background-attachment: fixed; background-repeat: no-repeat;">
        <div style="position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0, 0, 0, 0.4);"></div>
    </section>

    <!-- Main Content -->
    <section class="content-section">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem; margin-top: 2rem;">
                    The NRCGA Golf Tournament is an annual fundraising event that brings together members of Nevada''s damage prevention community for a day of golf, networking, and fun. Proceeds from the tournament directly support NRCGA''s outreach, education, and damage prevention programs across the state.
                </p>

                <div style="background: var(--bg-light); padding: 2rem; border-radius: 12px; margin: 2rem 0;">
                    <h3 style="margin-bottom: 1.5rem; color: var(--primary);">How Your Support Helps</h3>
                    <ul style="list-style: none; padding: 0; display: flex; flex-direction: column; gap: 1rem;">
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Funds safety training programs for excavators and locators</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Supports community outreach and public awareness campaigns</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Enables recognition programs like the Silver Shovel Awards</span>
                        </li>
                        <li style="display: flex; align-items: flex-start; gap: 0.75rem;">
                            <span style="color: var(--primary); font-size: 1.25rem;">✓</span>
                            <span>Helps organize events like 811 Day and the Utility Locate Rodeo</span>
                        </li>
                    </ul>
                </div>

                <h2 style="margin-top: 3rem; margin-bottom: 1.5rem;">Tournament Details</h2>
                <p style="margin-bottom: 2rem; color: var(--text-light);">
                    The NRCGA Golf Tournament typically includes:
                </p>

                <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 1.5rem; margin-top: 2rem;">
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">18-Hole Tournament</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Scramble format with prizes for top teams</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Networking Opportunities</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Connect with industry professionals and stakeholders</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Sponsorship Packages</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Multiple sponsorship levels available for businesses</p>
                    </div>
                    <div style="padding: 1.5rem; background: white; border-radius: 8px; border-left: 4px solid var(--primary);">
                        <h3 style="margin-bottom: 0.5rem; color: var(--primary);">Awards & Recognition</h3>
                        <p style="font-size: 0.9375rem; color: var(--text-light);">Prizes, raffles, and recognition for participants</p>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <!-- Get Involved CTA -->
    <section class="content-section bg-light">
        <div class="container">
            <div class="cta-content" style="text-align: center;">
                <h2>Get Involved</h2>
                <p>Click here to view your committee enrollment.</p>
                <div style="display: flex; justify-content: center; gap: 1.5rem; margin-top: 3rem; flex-wrap: wrap;">
                    <a href="committee-enrollment.html" class="btn btn-primary">Committee Enrollment</a>
                </div>
                <br>
                <p>Interested in participating in or sponsoring the golf tournament?</p>
                <div style="display: flex; justify-content: center; gap: 1.5rem; margin-top: 3rem; flex-wrap: wrap;">
                    <a href="contact.html" class="btn btn-primary">Contact Us</a>
                </div>
            </div>
        </div>
    </section>', NULL, 1, 0);
