RCGA''s broader recognition efforts. We also celebrate excavators who achieve zero at-fault damages and build a safety-first culture.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"View All Excavators who had Zero At-Fault Damages!","url":"zero-at-fault-damages.html","style":{"align":"left"}}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Get Involved","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Click here to view your committee enrollment.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Committee Enrollment","url":"committee-enrollment.html","style":{"align":"left"}},{"type":"text","body":"Interested in participating in or sponsoring this event?","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Contact Us","url":"contact.html","style":{"align":"left"}}]}]', '<!-- Southern Nevada Section -->
    <section class="content-section">
        <div class="container">
            <div class="content-text" style="text-align: center; max-width: 900px; margin: 0 auto;">
                
                <!-- Future Registration flyer Placeholder
                <h2>Join Us In Celebrating Damage Prevention Excellence!</h2>
                <div style="margin-bottom: 2rem; text-align: center;">
                    <img src="assets/images/programs/silver shovel/silvershovelflyer26.png" alt="Silver Shovel Award" style="width: 100%; max-width: 800px; border-radius: 12px; box-shadow: var(--shadow-md);" onerror="this.style.display=''none''">
                <div style="margin: 2rem 0; text-align: center;">
  <a
    href="https://luma.com/event/evt-QqenO6E53c39914"
    class="luma-checkout--button"
    data-luma-action="checkout"
    data-luma-event-id="evt-QqenO6E53c39914"
    style="padding: 1.5rem 3rem; font-size: 1.25rem; display: inline-block; min-width: 250px;"
  >
    Register for Event!
  </a>
</div>
                
<script id="luma-checkout" src="https://embed.lu.ma/checkout-button.js"></script>
                </div>
            </div> -->
            
            <div class="content-text" style="text-align: center; max-width: 900px; margin: 0 auto;">
                <h2>The Best of The Best</h2>
                
                <div style="margin-bottom: 2rem; text-align: center;">
                    <img src="assets/images/programs/silver shovel/jbmjumbo.jpg" alt="Silver Shovel Award" style="width: 100%; max-width: 800px; border-radius: 12px; box-shadow: var(--shadow-md);" onerror="this.style.display=''none''">
                </div>
                
                <div style="background: var(--bg-light); padding: 2rem; border-radius: 12px; margin: 2rem 0; text-align: center;">
                    <img src="assets/images/programs/silver shovel/shovelhandoff.jpg" alt="2026 Silver Shovel Award Winner - JBM Underground" style="width: 100%; max-width: 600px; border-radius: 8px; margin-bottom: 1.5rem; box-shadow: var(--shadow-md);" onerror="this.style.display=''none''">
                    <h3 style="color: var(--primary); margin-bottom: 1rem; font-size: 1.5rem;">Congratulations, JBM Underground!</h3>
                    <p style="font-size: 1.25rem; font-weight: 600; margin-bottom: 0.5rem;">2026 Silver Shovel Award Winner!</p>
                    <p style="color: var(--text-light);">Award Celebration: April 18, 2026 at Lees Family Forum, Las Vegas</p>
                </div>

                

                <h3 style="margin-top: 3rem; margin-bottom: 1.5rem;">Silver Shovel Hall of Fame</h3>
                <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1rem; margin-top: 1.5rem;">
                    <div style="padding: 1.5rem; background: var(--primary); color: white; border-radius: 8px; text-align: center; font-weight: 600;">C&S Company<br><span style="font-size: 0.875rem; font-weight: 400;">2025</span></div>
                    <div style="padding: 1.5rem; background: var(--primary); color: white; border-radius: 8px; text-align: center; font-weight: 600;">Southwest Gas<br><span style="font-size: 0.875rem; font-weight: 400;">2024</span></div>
                    <div style="padding: 1.5rem; background: var(--primary); color: white; border-radius: 8px; text-align: center; font-weight: 600;">Las Vegas Paving<br><span style="font-size: 0.875rem; font-weight: 400;">2023</span></div>
                    <div style="padding: 1.5rem; background: var(--primary); color: white; border-radius: 8px; text-align: center; font-weight: 600;">Lone Mountain Excavation<br><span style="font-size: 0.875rem; font-weight: 400;">2021</span></div>
                    <div style="padding: 1.5rem; background: var(--primary); color: white; border-radius: 8px; text-align: center; font-weight: 600;">Tab Contractors<br><span style="font-size: 0.875rem; font-weight: 400;">2018</span></div>
                    <div style="padding: 1.5rem; background: var(--primary); color: white; border-radius: 8px; text-align: center; font-weight: 600;">Future Infrastructure Services<br><span style="font-size: 0.875rem; font-weight: 400;">2019</span></div>
                    <div style="padding: 1.5rem; background: var(--primary); color: white; border-radius: 8px; text-align: center; font-weight: 600;">Silver Lake Construction<br><span style="font-size: 0.875rem; font-weight: 400;">2017</span></div>
                    <div style="padding: 1.5rem; background: var(--primary); color: white; border-radius: 8px; text-align: center; font-weight: 600;">Byrd Underground<br><span style="font-size: 0.875rem; font-weight: 400;">2016</span></div>
                </div>

            
            </div>
        </div>
    </section>

    <!-- Northern Nevada Section 
    <section class="content-section bg-light">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto;">
                <h2>Northern Nevada</h2>
                <p style="font-size: 1.125rem; line-height: 1.8; margin-bottom: 2rem;">
                    In 2024, the Northern Nevada Silver Shovel Committee began a unique effort to target and celebrate excavators practicing safe digging. Bimonthly, the committee identifies an outstanding contractor and acknowledges their outstanding safety practices with a banner to display at the company office and a BBQ lunch courtesy of the NRCGA.
                </p>
                <p style="margin-bottom: 2rem; color: var(--text-light);">
                    Scroll down to learn about the companies identified and awarded for their outstanding performances.
                </p>

                <div style="margin-top: 3rem;">
                    <h3 style="margin-bottom: 1.5rem;">Titan Electric, June/July 2024</h3>
                    <div style="background: white; padding: 2rem; border-radius: 12px; border-left: 4px solid var(--primary);">
                        <p style="margin-bottom: 1rem;">
                            The Silver Shovel Committee selected Titan Electrical Contracting as its first award recipient. Titan is a prominent electric, traffic signal and communications install contractor working throughout Northern Nevada.
                        </p>
                        <p style="margin-bottom: 1rem;">
                            The Reno Oddie Street Rehabilitation Project, which concluded the summer of 2024, was a two-year process involving Titan and several contractors. The Titan crew rose to the occasion every day in challenging conditions, protecting all underground facilities.
                        </p>
                        <p>
                            Going out of the way to make sure locate marks were maintained, working daily with utility locators, assuring standby inspectors were on site when working around high profile facilities were everyday practices for Titan.
                        </p>
                        <p style="margin-top: 1rem; font-weight: 600; color: var(--primary);">Great job, Titan Electric!</p>
                    </div>
                </div>

                <div style="margin-top: 3rem;">
                    <h3 style="margin-bottom: 1.5rem;">Mears Pipeline, August/September 2024</h3>
                    <div style="background: white; padding: 2rem; border-radius: 12px; border-left: 4px solid var(--primary);">
                        <p style="margin-bottom: 1rem;">
                            Arguably, one could consider the risk level for damaging any utility to be very high for an excavator that performs the type of work Mears does day in day out. Their work scope and feet of ditch excavated exposes them to underground utilities all day, month, and year.
                        </p>
                        <p style="margin-bottom: 1rem; font-weight: 600;">
                            We feel Mears Pipeline damage metrics set them apart from the pack. From April 2023 to current in Northern Nevada, Mears reports:
                        </p>
                        <ul style="list-style: none; padding: 0; margin: 1rem 0;">
                            <li style="padding: 0.5rem 0; border-bottom: 1px solid var(--border);">255,262.05 man hours</li>
                            <li style="padding: 0.5rem 0; border-bottom: 1px solid var(--border);">228,245 feet of installed natural gas and electric underground</li>
                            <li style="padding: 0.5rem 0; border-bottom: 1px solid var(--border);">43.22 miles, all distribution (public streets, subdivisions, state highways)</li>
                            <li style="padding: 0.5rem 0; border-bottom: 1px solid var(--border);">2,537 protective meters installed (4 excavations for each, in the middle of many residential utilities at the structure)</li>
                            <li style="padding: 0.5rem 0; border-bottom: 1px solid var(--border);">73 employees</li>
                            <li style="padding: 0.5rem 0; font-weight: 600; color: var(--primary); font-size: 1.125rem;"><strong>Zero Damages</strong></li>
                        </ul>
                        <p style="margin-top: 1rem; font-weight: 600; color: var(--primary);">
                            Hats off to this crew! Maybe Mears is breaking new ground. . . If we all tracked our metrics in this manner, it could be quite a motivator for our teams.
                        </p>
                    </div>
                </div>

                <div style="margin-top: 3rem;">
                    <h3 style="margin-bottom: 1.5rem;">F&P Construction, December 2024</h3>
                    <div style="background: white; padding: 2rem; border-radius: 12px; border-left: 4px solid var(--primary);">
                        <p style="margin-bottom: 1rem;">
                            F&P Construction has been a prominent Northern Nevada "staple" for years, specializing in "moving mountains." F&P takes on large commercial projects in Reno along with the massive data center/high tech development work taking place in the TRIC/USA Parkway area.
                        </p>
                        <p style="margin-bottom: 1rem;">
                            The F&P Safety group always hits the bar in areas of ticket management, high profile standby scheduling, communicating with all utility locators and training aspects of safe excavation around all utilities.
                        </p>
                        <p style="margin-bottom: 1rem;">
                            We had the opportunity to address F&P ownership, management, and their safety committee on December 18. It was clear they put a premium on safety, and very much appreciated an outside group such as the NRCGA recognizing their hard work and commitment.
                        </p>
                        <p>
                            As F&P crews are very spread out, their safety group the intent to present each crew the banner awarded yesterday, thanking all their employees for their commitment.
                        </p>
                    </div>
                </div>
            </div>
        </div>
    </section> -->

    <!-- Additional Recognition -->
    <section class="content-section bg-light">
        <div class="container">
            <div class="content-text" style="max-width: 900px; margin: 0 auto; text-align: center;">
                <h2>2026 Zero At-Fault Damages List</h2>
                <p style="font-size: 1.125rem; line-height: 1.8; margin-top: 1.5rem; margin-bottom: 2rem;">
                    The Silver Shovel Award is part of NRCGA''s broader recognition efforts. We also celebrate excavators who achieve zero at-fault damages and build a safety-first culture.
                </p>
                <a href="zero-at-fault-damages.html" class="btn btn-primary">View All Excavators who had Zero At-Fault Damages!</a>
            </div>
        </div>
    </section>

    <!-- Get Involved CTA -->
    <section class="content-section bg-light">
        <div class="container">
            <div class="cta-content" style="text-align: center;">
                <h2>Get Involved</h2>
                <p>Click here to view your committee enrollment.</p>
                <div style="display: flex; justify-content: center; gap: 1.5rem; margin-top: 3rem; flex-wrap: wrap;">
                    <a href="committee-enrollment.html" class="btn btn-primary">Committee Enrollment</a>
                </div>
                <br>
                <p>Interested in participating in or sponsoring this event?</p>
                <div style="display: flex; justify-content: center; gap: 1.5rem; margin-top: 3rem; flex-wrap: wrap;">
                    <a href="contact.html" class="btn btn-primary">Contact Us</a>
                </div>
            </div>
        </div>
    </section>', NULL, 1, 0);
