INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, body_html, regions_json, published, is_custom)
     VALUES ('00000000-0000-4000-8000-00000585238d', 'about', 'Nevada Regional Common Ground Alliance', 'About Us', 'Promoting public safety and damage prevention through education, collaboration, and continuous improvement.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"columns","cols":2,"gap":"md","columns":[[{"type":"heading","level":2,"text":"Our Mission","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"NRCGA is dedicated to promoting public safety and damage prevention across Nevada. We bring together excavators, utility operators, locators, and stakeholders to build a culture of safety through education, collaboration, and continuous improvement.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Every dig matters. Every call to 811 prevents potential damage, protects lives, and ensures the reliability of essential services. We''re committed to building a safer Nevada where underground infrastructure is protected and respected.","style":{"align":"left","textSize":"md","textColor":"default"}}],[{"type":"image","url":"assets/images/programs/nrcga-meeting.jpg","alt":"NRCGA members collaborating","caption":"","width":"full","align":"left"},{"type":"heading","level":3,"text":"Our Impact","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"• Education & Training Programs\n• Damage Prevention Initiatives\n• Community Outreach\n• Industry Collaboration","style":{"align":"left","textSize":"md","textColor":"default"}}]]}]}]', '<section class="content-section">
        <div class="container">
            <div class="content-grid">
                <div class="content-text">
                    <h2>Our Mission</h2>
                    <p>
                        NRCGA is dedicated to promoting public safety and damage prevention across Nevada. We bring together
                        excavators, utility operators, locators, and stakeholders to build a culture of safety through
                        education, collaboration, and continuous improvement.
                    </p>
                    <p>
                        Every dig matters. Every call to 811 prevents potential damage, protects lives, and ensures the
                        reliability of essential services. We''re committed to building a safer Nevada where underground
                        infrastructure is protected and respected.
                    </p>
                </div>
                <div class="content-visual">
                    <img src="assets/images/programs/nrcga-meeting.jpg" alt="NRCGA members collaborating" style="width: 100%; border-radius: 12px; box-shadow: var(--shadow-md); margin-bottom: 1.5rem;" onerror="this.style.display=''none''">
                    <div class="visual-card">
                        <h3>Our Impact</h3>
                        <ul class="impact-list">
                            <li>Education &amp; Training Programs</li>
                            <li>Damage Prevention Initiatives</li>
                            <li>Community Outreach</li>
                            <li>Industry Collaboration</li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    </section>', NULL, 1, 0);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, body_html, regions_json, published, is_custom)
     VALUES ('00000000-0000-4000-8000-00000030f4df', 'home', 'home', '', '', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Protecting Nevada''s Underground Infrastructure","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Every dig matters. Every call to 811 prevents potential damage, protects lives, and ensures the reliability of essential services. We''re building a culture of safety across Nevada through collaboration, education, and continuous improvement.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"EPR Codes","url":"https://usanorth811.org/assets/PDF/NV-EPR-Codes_Update-Announcment.pdf","style":{"align":"left"}},{"type":"cta_button","label":"Nevada Excavation Handbook","url":"https://usanorth811.org/assets/PDF/Nevada-2025-Handbook.pdf","style":{"align":"left"}},{"type":"cta_button","label":"Nevada Excavation Law (English)","url":"https://usanorth811.org/assets/PDF/Nevada-2025-Law.pdf","style":{"align":"left"}},{"type":"cta_button","label":"Nevada Excavation Law (Spanish)","url":"https://usanorth811.org/assets/PDF/NV-LAW-Spanish.pdf","style":{"align":"left"}}]}]', '<!-- Mission Statement -->
    <section class="mission">
        <div class="container">
            <div class="mission-content">
                <h2 class="section-title">Protecting Nevada''s Underground Infrastructure</h2>
                <p class="mission-text">
                    Every dig matters. Every call to 811 prevents potential damage, protects lives, and ensures 
                    the reliability of essential services. We''re building a culture of safety across Nevada through 
                    collaboration, education, and continuous improvement.
                </p>
                <div style="margin-top: 2rem; display: flex; flex-direction: column; gap: 1rem; align-items: center;">
                    <div style="display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap;">
                        <a href="https://usanorth811.org/assets/PDF/NV-EPR-Codes_Update-Announcment.pdf" target="_blank" rel="noopener noreferrer" class="btn btn-primary">EPR Codes</a>
                        <a href="https://usanorth811.org/assets/PDF/Nevada-2025-Handbook.pdf" target="_blank" rel="noopener noreferrer" class="btn btn-secondary">Nevada Excavation Handbook</a>
                    </div>
                    <div style="display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap;">
                        <a href="https://usanorth811.org/assets/PDF/Nevada-2025-Law.pdf" target="_blank" rel="noopener noreferrer" class="btn btn-primary">Nevada Excavation Law (English)</a>
                        <a href="https://usanorth811.org/assets/PDF/NV-LAW-Spanish.pdf" target="_blank" rel="noopener noreferrer" class="btn btn-secondary">Nevada Excavation Law (Spanish)</a>
                    </div>
                </div>
            </div>
        </div>
    </section>', '{"hero_html":"<div class=\"hero-badge\">Nevada Regional Common Ground Alliance</div>\r\n                <h1 class=\"hero-title\">\r\n                    Safer digging starts with<br>\r\n                    <span class=\"highlight\">clear communication</span><br>\r\n                    and solid process.\r\n                </h1>\r\n                <p class=\"hero-description\">\r\n                    NRCGA supports Nevada''s damage prevention community with education, training, and programs \r\n                    that promote safe excavation and protection of buried infrastructure.\r\n                </p>\r\n                <div class=\"hero-actions\">\r\n                    <a href=\"about.html\" class=\"btn btn-primary\">Learn About The NRCGA</a>\r\n                    <a href=\"about-811.html\" class=\"btn btn-secondary\">Learn About 811</a>\r\n                    <a href=\"training.html\" class=\"btn btn-primary\">View Training</a>\r\n                </div>","contact_html":"<h2>Get in Touch</h2>\r\n                    <p>Have questions? Want to get involved? We''d love to hear from you.</p>\r\n                    <div class=\"contact-details\">\r\n                        <div class=\"contact-item\">\r\n                            <strong>Email</strong>\r\n                            <a href=\"mailto:info@nrcga.org\">info@nrcga.org</a>\r\n                        </div>\r\n                        <div class=\"contact-item\">\r\n                            <strong>Response Time</strong>\r\n                            <span>1–2 business days</span>\r\n                        </div>\r\n                    </div>"}', 1, 0);
