     VALUES ('00000000-0000-4000-8000-0000ae169be8', 'bylaws', 'NRCGA Bylaws & Standing Rules', 'Governance', 'The bylaws govern NRCGA''s structure, membership, and decision-making processes. The standing rules provide operational guidelines and procedures for NRCGA activities.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Bylaws","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"cta_button","label":"Download PDF","url":"assets/pdfs/NRCGA-2024-Bylaws-Revision-signed.pdf","style":{"align":"left"}},{"type":"text","body":"<p>Your browser does not support PDFs. <a href=\"assets/pdfs/NRCGA-2024-Bylaws-Revision-signed.pdf\" download>Download the PDF</a> instead.</p>","style":{"align":"left","textSize":"md","textColor":"default"}}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Standing Rules","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"cta_button","label":"Download PDF","url":"assets/pdfs/NRCGA-Standing-Rules.pdf","style":{"align":"left"}},{"type":"text","body":"<p>Your browser does not support PDFs. <a href=\"assets/pdfs/NRCGA-Standing-Rules.pdf\" download>Download the PDF</a> instead.</p>","style":{"align":"left","textSize":"md","textColor":"default"}}]}]', '<!-- Bylaws Content -->
