        </div>
    </section>', NULL, 1, 0);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, body_html, regions_json, published, is_custom)
     VALUES ('00000000-0000-4000-8000-0000e79372da', 'data-maps', 'Nevada Data', 'Resources', 'Nevada damage prevention data', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"CGA DIRT Report","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Access damage prevention data and statistics for Nevada based on the CGA DIRT report.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Access NV DIRT Data","url":"https://public.tableau.com/shared/CN836Y9G7?:display_count=y&:origin=viz_share_link&:embed=y","style":{"align":"left"}},{"type":"heading","level":3,"text":"CGA Root Cause Flow Chart","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"The Common Ground Alliance (CGA) Root Cause Flow Chart is a standardized tool designed to help identify and classify the root causes of damage incidents when reporting through the Damage Information Reporting Tool (DIRT). This flow chart provides a systematic approach to analyzing damage events, helping to ensure consistent and accurate root cause classification across the industry.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Use this flow chart as a guide when submitting DIRT reports to help identify the primary contributing factors and root causes of damage incidents. Accurate root cause identification helps the industry better understand damage trends and develop targeted prevention strategies.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"View Root Cause Flow Chart","url":"assets/images/DIRT-root-cause-flow-chart-UPDATED-12_19_24.jpg","style":{"align":"left"}}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Nevada Damage Prevention Guide","style":{"align":"left","textSize":"lg","textColor":"default"}}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"About This Guide","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"This guide provides an interactive resource to all things damage prevention related across Nevada.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"The map is regularly updated with the latest damage prevention information. For questions about this guide or to request additional information, please contact NRCGA.","style":{"align":"left","textSize":"md","textColor":"default"}}]}]', '<!-- NV Field Data Link -->
    <section class="content-section">
        <div class="container">
            <div class="section-header">
                <h2 class="section-title">CGA DIRT Report</h2>
                <p class="section-subtitle">Access damage prevention data and statistics for Nevada based on the CGA DIRT report.</p>
                <div style="display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; margin-top: 1.5rem;">
                        <a href="https://public.tableau.com/shared/CN836Y9G7?:display_count=y&:origin=viz_share_link&:embed=y" class="btn btn-primary" target="_blank" rel="noopener noreferrer">Access NV DIRT Data</a>
                    </div>
            </div>

            <!--CGA Root Cause Flow Chart-->
            <div class="cga-info-box" style="max-width: 800px; margin: 2rem auto 0; padding: 1.5rem; background: var(--bg-secondary); border-radius: 12px;">
            
                <h3 style="font-size: 1.25rem; margin-bottom: 1rem;">CGA Root Cause Flow Chart</h3>
                <p style="line-height: 1.7; margin-bottom: 0.5rem;">
                    The Common Ground Alliance (CGA) Root Cause Flow Chart is a standardized tool designed to help identify and classify 
                    the root causes of damage incidents when reporting through the Damage Information Reporting Tool (DIRT). This flow chart 
                    provides a systematic approach to analyzing damage events, helping to ensure consistent and accurate root cause 
                    classification across the industry.
                </p>
                <p style="line-height: 1.7; margin-top: 0.5rem; margin-bottom: 1.5rem;">
                    Use this flow chart as a guide when submitting DIRT reports to help identify the primary contributing factors and root 
                    causes of damage incidents. Accurate root cause identification helps the industry better understand damage trends and 
                    develop targeted prevention strategies.
                </p>
                <div style="text-align: center;">
                    <a href="assets/images/DIRT-root-cause-flow-chart-UPDATED-12_19_24.jpg" class="btn btn-secondary" target="_blank" rel="noopener noreferrer">View Root Cause Flow Chart</a>
                </div>
            </div>
        </div>
    </section>

    <!-- Interactive Map -->
    <section class="content-section bg-light">
        <div class="container">
            <div class="section-header">
                <h2 class="section-title">Nevada Damage Prevention Guide</h2>
            </div>

            <div class="map-container">
                <div id="nrcga-map"></div>
            </div>
        </div>
    </section>

    <!-- Map Information -->
    <section class="content-section bg-light">
        <div class="container">
            <div class="content-text" style="max-width: 800px; margin: 0 auto;">
                <h2>About This Guide</h2>
                <p>
                    This guide provides an interactive resource to all things damage prevention related across Nevada.
                </p>
                <p style="margin-top: 1.5rem;">
                    The map is regularly updated with the latest damage prevention information. For questions about 
                    this guide or to request additional information, please <a href="contact.html">contact NRCGA</a>.
                </p>
                <!--
                <div style="margin-top: 2rem; padding: 1.5rem; background: rgba(255, 193, 7, 0.1); border-left: 4px solid #ffc107; border-radius: 8px;">
                    <p style="margin: 0; color: var(--text-secondary); font-size: 0.9375rem; line-height: 1.7;">
                        <strong>Data Disclaimer:</strong> The information displayed in this guide is provided for informational purposes only. 
                        While NRCGA strives to maintain accurate and up-to-date data, the information may contain inaccuracies, errors, or omissions. 
                        The data is provided "as is" without warranty of any kind, and NRCGA does not guarantee the accuracy, completeness, or 
                        reliability of the information. Users should verify critical information independently and not rely solely on this guide
                        for decision-making purposes.
                    </p>
                </div> -->
            </div>
        </div>
    </section>', NULL, 1, 0);
